function convertToWordLayout(cloned: HTMLElement) {
  // 1. Header Image
  const headerContainer = cloned.querySelector('#report-header-container');
  if (headerContainer) {
    const headerImg = headerContainer.querySelector('img');
    if (headerImg) {
      headerImg.setAttribute('width', '794');
      headerImg.style.width = '794px';
      headerImg.style.height = 'auto';
    }
  }

  // 2. Body Split (Left Col / Right Col)
  const contentSplit = cloned.querySelector('#report-content-split');
  const leftCol = cloned.querySelector('#report-left-col');
  const rightCol = cloned.querySelector('#report-right-col');

  if (contentSplit && leftCol) {
    // Convert the flex container into a table
    const table = document.createElement('table');
    table.setAttribute('width', '100%');
    table.setAttribute('cellpadding', '0');
    table.setAttribute('cellspacing', '0');
    table.style.width = '100%';

    const tr = document.createElement('tr');
    tr.setAttribute('valign', 'top');

    const tdLeft = document.createElement('td');
    tdLeft.setAttribute('width', rightCol ? '66%' : '100%');
    tdLeft.style.width = rightCol ? '66%' : '100%';
    tdLeft.style.verticalAlign = 'top';
    tdLeft.appendChild(leftCol);
    tr.appendChild(tdLeft);

    if (rightCol) {
      const tdRight = document.createElement('td');
      tdRight.setAttribute('width', '34%');
      tdRight.style.width = '34%';
      tdRight.style.verticalAlign = 'top';
      tdRight.appendChild(rightCol);
      tr.appendChild(tdRight);

      // Fix right images
      const rightImages = Array.from(rightCol.querySelectorAll('img'));
      rightImages.forEach(img => {
        img.setAttribute('width', '240');
        img.style.width = '240px';
        img.style.height = 'auto';
        img.style.marginBottom = '6px';

        // Remove object-fit and width 100% since they break in Word
        img.style.objectFit = '';
      });
    }

    table.appendChild(tr);
    contentSplit.parentNode?.replaceChild(table, contentSplit);
  }

  // 3. Bottom Images
  const bottomImagesRow = cloned.querySelector('#report-bottom-images');
  if (bottomImagesRow) {
    const bottomImages = Array.from(bottomImagesRow.querySelectorAll('img'));

    const table = document.createElement('table');
    table.setAttribute('width', '100%');
    table.setAttribute('cellpadding', '0');
    table.setAttribute('cellspacing', '0');
    table.style.width = '100%';

    const tr = document.createElement('tr');
    tr.setAttribute('valign', 'top');

    bottomImages.forEach(img => {
      const td = document.createElement('td');
      td.setAttribute('width', '50%');
      td.style.width = '50%';
      td.style.paddingRight = '8px';

      img.setAttribute('width', '350');
      img.style.width = '350px';
      img.style.height = 'auto';
      img.style.objectFit = '';

      // Move img to td, preserving NBI labels if any
      const imgContainer = img.parentElement;
      if (imgContainer) {
        td.appendChild(imgContainer);
      }
      tr.appendChild(td);
    });

    table.appendChild(tr);
    bottomImagesRow.parentNode?.replaceChild(table, bottomImagesRow);
  }

  // 4. Footer
  const footerLeft = cloned.querySelector('#footer-left-doctors');
  const footerRight = cloned.querySelector('#footer-right-weo');
  if (footerLeft && footerRight) {
    const footerContainer = footerLeft.parentElement;
    if (footerContainer) {
      const table = document.createElement('table');
      table.setAttribute('width', '100%');
      table.setAttribute('cellpadding', '0');
      table.setAttribute('cellspacing', '0');
      table.style.width = '100%';

      const tr = document.createElement('tr');
      tr.setAttribute('valign', 'bottom');

      const tdLeft = document.createElement('td');
      tdLeft.setAttribute('width', '60%');
      tdLeft.style.width = '60%';
      tdLeft.style.verticalAlign = 'bottom';

      // Doctors need to be laid out horizontally if there are multiple.
      const doctorsTable = document.createElement('table');
      const docTr = document.createElement('tr');
      docTr.setAttribute('valign', 'top');
      Array.from(footerLeft.children).forEach(docDiv => {
        const docTd = document.createElement('td');
        docTd.style.paddingRight = '20px';
        docTd.appendChild(docDiv);
        docTr.appendChild(docTd);
      });
      doctorsTable.appendChild(docTr);
      tdLeft.appendChild(doctorsTable);

      const tdRight = document.createElement('td');
      tdRight.setAttribute('width', '40%');
      tdRight.setAttribute('align', 'right');
      tdRight.style.width = '40%';
      tdRight.style.textAlign = 'right';
      tdRight.style.verticalAlign = 'bottom';
      tdRight.appendChild(footerRight);

      const weoImg = footerRight.querySelector('img');
      if (weoImg) {
        weoImg.setAttribute('height', '42');
        weoImg.style.height = '42px';
        weoImg.style.width = 'auto';
      }

      tr.appendChild(tdLeft);
      tr.appendChild(tdRight);
      table.appendChild(tr);

      footerContainer.parentNode?.replaceChild(table, footerContainer);
    }
  }

  // Final cleanup: remove problematic flex styles on the wrapper
  cloned.style.display = 'block';
  cloned.style.height = 'auto';
}

