const imageToBase64ForWord = async (
  src: string, cropW: number, cropH: number, brightness: number, contrast: number
): Promise<string> => {
  return new Promise((resolve) => {
    const img = new Image();
    img.crossOrigin = "anonymous";
    img.onload = () => {
      try {
        const SCALE = 2;
        const cw = cropW * SCALE, ch = cropH * SCALE;
        const canvas = document.createElement("canvas");
        canvas.width = cw; canvas.height = ch;
        const ctx = canvas.getContext("2d")!;
        const imgRatio = img.width / img.height, tgtRatio = cw / ch;
        let drawW, drawH, ox, oy;
        if (imgRatio > tgtRatio) {
          drawH = ch; drawW = img.width * (ch / img.height);
          ox = (cw - drawW) / 2; oy = 0;
        } else {
          drawW = cw; drawH = img.height * (cw / img.width);
          ox = 0; oy = (ch - drawH) / 2;
        }
        ctx.filter = `brightness(${brightness / 100}) contrast(${contrast / 100})`;
        ctx.drawImage(img, ox, oy, drawW, drawH);
        resolve(canvas.toDataURL("image/jpeg", 0.93));
      } catch { resolve(src); }
    };
    img.onerror = () => resolve(src);
    img.src = src;
  });
};

const localImageToBase64 = async (path: string): Promise<string> => {
  try {
    const resp = await fetch(path);
    const blob = await resp.blob();
    return new Promise<string>((res, rej) => {
      const reader = new FileReader();
      reader.onload = () => res(reader.result as string);
      reader.onerror = rej;
      reader.readAsDataURL(blob);
    });
  } catch { return ""; }
};

